import * as React from "react";
import { Box, Grid, Card, CardContent, Typography, Modal, Button, TextField } from "@mui/material";
import axios from "axios";

// Define a type for the venue
interface Venue {
  title: string;
  subtitle: string;
  description: string;
  vendorId: number;
}

// Define a type for vendor availability
interface VendorAvailability {
  availabilityId: number;
  date: string;
  isBooked: boolean;
  vendorId: number;
}

export default function VenuesPage() {
  const [selectedVenue, setSelectedVenue] = React.useState<Venue | null>(null);
  const [availableVenues, setAvailableVenues] = React.useState<Venue[]>([]);
  const [selectedDate, setSelectedDate] = React.useState<string>("");

  const handleOpen = (venue: Venue) => {
    setSelectedVenue(venue);
  };

  const handleClose = () => {
    setSelectedVenue(null);
  };

  const handleDateChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const date = event.target.value;
    setSelectedDate(date);
  };

  // Fetch available venues based on the selected date
  const fetchAvailableVenues = async () => {
    if (!selectedDate) {
      return; // No date selected
    }

    try {
      const response = await axios.get(`/api/available-venues?date=${selectedDate}`);
      setAvailableVenues(response.data);
    } catch (error) {
      console.error("Error fetching available venues:", error);
    }
  };

  // Trigger availability check when the date changes
  React.useEffect(() => {
    fetchAvailableVenues();
  }, [selectedDate]);

  return (
    <Box
      sx={{
        width: "100%",
        minHeight: "100vh",
        backgroundColor: "#f5f5f5",
        padding: 2,
        boxSizing: "border-box",
      }}
    >
      {/* Header */}
      <Typography
        variant="h4"
        sx={{ fontWeight: "bold", marginBottom: 3, textAlign: "center" }}
      >
        Explore Venues
      </Typography>

      {/* Date Picker */}
      <TextField
        label="Select Date"
        type="date"
        value={selectedDate}
        onChange={handleDateChange}
        sx={{ marginBottom: 3, display: "block", marginX: "auto" }}
        InputLabelProps={{
          shrink: true,
        }}
      />

      {/* Grid Layout for Boxes */}
      <Grid container spacing={2} sx={{ justifyContent: "center" }}>
        {/* Dynamically generate each available venue box */}
        {availableVenues.map((venue, index) => (
          <Grid item xs={6} key={index}>
            <Card
              sx={{
                borderRadius: 6,
                boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                overflow: "hidden",
                backgroundColor: "transparent",
                display: "flex",
                flexDirection: "column",
                height: "100%",
              }}
              onClick={() => handleOpen(venue)} // Open the modal on click
            >
              <Box
                sx={{
                  width: "100%",
                  aspectRatio: "4 / 3",
                  backgroundColor: "#d0e7ff",
                }}
              />
              <CardContent
                sx={{
                  paddingTop: 2,
                  backgroundColor: "#fff",
                  height: "calc(1 / 6 * 100%)",
                  marginTop: "auto",
                  flexShrink: 0,
                  flexGrow: 0,
                }}
              >
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: "bold",
                    fontSize: "calc(1.2vw + 0.8rem)",
                    textAlign: "center",
                    lineHeight: 1.2,
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                  }}
                >
                  {venue.title}
                </Typography>
                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{
                    fontSize: "calc(0.8vw + 0.6rem)",
                    textAlign: "center",
                    lineHeight: 1,
                    overflow: "hidden",
                    whiteSpace: "nowrap",
                    textOverflow: "ellipsis",
                    marginTop: 1,
                  }}
                >
                  {venue.subtitle}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Modal for displaying venue details */}
      <Modal
        open={!!selectedVenue}
        onClose={handleClose}
        sx={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <Box
          sx={{
            width: "85%", // Increased width to 85%
            backgroundColor: "white",
            padding: 3,
            borderRadius: 2,
            height: "40%", // Adjusted max height to 90% of the viewport height
            overflowY: "auto", // Enables vertical scrolling
            position: "relative",
          }}
        >
          <Button
            onClick={handleClose}
            sx={{
              position: "absolute",
              top: 10,
              right: 10,
              fontSize: "1.5rem",
              backgroundColor: "transparent",
              color: "black",
              border: "none",
              cursor: "pointer",
            }}
          >
            X
          </Button>
          <Typography variant="h4" sx={{ fontWeight: "bold" }}>
            {selectedVenue?.title}
          </Typography>
          <Typography variant="body1" sx={{ marginBottom: 2 }}>
            {selectedVenue?.description}
          </Typography>

          {/* Book Button moved to bottom-right corner */}
          <Box
            sx={{
              position: "absolute",
              bottom: 10,
              right: 10,
            }}
          >
            <Button
              variant="contained"
              sx={{
                backgroundColor: "#F7C5AD", // Custom button color
                color: "#000", // Ensures the text is visible
                '&:hover': {
                  backgroundColor: "#f7b59b", // Slightly darker hover color
                },
                padding: "8px 20px", // Smaller button
              }}
            >
              Book
            </Button>
          </Box>
        </Box>
      </Modal>
    </Box>
  );
}


